using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Reflection;
using System.Windows.Controls;
namespace BrowserManager {
    public static class DataManagementTests {
        const string Password="FAKE master password 123";
        static bool Reject(Action action){try{action();return false;}catch{return true;}}
        public static void Run(string report){var rows=new List<string>();Action<bool,string> check=(pass,name)=>{if(!pass)throw new Exception(name);rows.Add("通过："+name);};
            string root=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(report)),"management-"+Guid.NewGuid().ToString("N")),old=Path.Combine(root,"old"),fixedHome=Path.Combine(root,"fixed");Directory.CreateDirectory(old);
            var store=new Store(old);store.PasswordIterations=10000;var data=Store.Initial();var account=Account.New("FAKE CN","CN");account.Password=" FAKE PASSWORD ";data.Accounts.Add(account);store.Save(data);store.EnableProtection(data,Password);
            string browser=Path.Combine(old,"data","browser","chrome",account.Id,"Default","Cookies");Directory.CreateDirectory(Path.GetDirectoryName(browser));File.WriteAllText(browser,"FAKE COOKIE STATE");string embedded=Path.Combine(old,"data","browser","webview2","EBWebView",EmbeddedPolicy.Profile(account.Id),"Preferences");Directory.CreateDirectory(Path.GetDirectoryName(embedded));File.WriteAllText(embedded,"FAKE WEBVIEW STATE");
            var selection=new NativeSelection{Format=1,AccountId=account.Id,Region="CN",ClientVersion="FAKE_VERSION",SavedNames="123456",RegisteredUtc=DateTime.UtcNow};NativeSelections.Save(Path.Combine(old,"cn-exp"),selection);
            byte[] vault=File.ReadAllBytes(store.FilePath);var inventory=DataDirectory.Inventory(old);var original=inventory.ToDictionary(p=>p.Key,p=>DataDirectory.Digest(p.Value));
            check(Reject(()=>DataDirectory.Ensure(old,Path.Combine(root,"blocked"),null,h=>{throw new InvalidOperationException("FAKE BROWSER RUNNING");}))&&!Directory.Exists(Path.Combine(root,"blocked")),"专用浏览器未退出时迁移不发布新目录");
            check(DataDirectory.Ensure(old,fixedHome,null,h=>{})==DataDirectory.Canonical(fixedHome)&&DataDirectory.Ready(fixedHome),"完整复制校验后启用固定资料位置");
            check(original.All(p=>p.Value==DataDirectory.Digest(Path.Combine(old,p.Key))&&p.Value==DataDirectory.Digest(Path.Combine(fixedHome,p.Key))),"原目录不变，密码库、浏览器和登记逐文件一致");
            var migrated=new Store(fixedHome);migrated.PasswordIterations=10000;check(migrated.IsLocked&&migrated.Unlock(Password).Accounts[0].Id==account.Id,"迁移不解密或重设保护，原主密码和账号标识有效");
            File.WriteAllText(Path.Combine(old,"data","FAKE_LATER"),"source later changed");check(DataDirectory.Ensure(old,fixedHome,null,h=>{})==DataDirectory.Canonical(fixedHome)&&!File.Exists(Path.Combine(fixedHome,"data","FAKE_LATER")),"后续升级沿用固定目录，不反复覆盖为旧资料");
            check(Reject(()=>DataDirectory.Ensure(old,Path.Combine(old,"nested"),null,h=>{})),"拒绝源目标重叠的目录迁移");
            string occupied=Path.Combine(root,"occupied");Directory.CreateDirectory(occupied);File.WriteAllText(Path.Combine(occupied,"keep"),"KEEP");check(Reject(()=>DataDirectory.Ensure(old,occupied,null,h=>{}))&&File.ReadAllText(Path.Combine(occupied,"keep"))=="KEEP","未完成的已有目标目录不会被覆盖");
            string failed=Path.Combine(root,"changed");bool altered=false;check(Reject(()=>DataDirectory.Ensure(old,failed,null,h=>{if(altered)File.WriteAllText(browser,"FAKE CHANGED");altered=true;}))&&!Directory.Exists(failed),"复制期间源资料变化会取消发布");
            string pack=Path.Combine(root,"full.bampack");FullBackup.Create(migrated,pack,null,h=>{});byte[] packet=FullBackup.ReadKeyPacket(pack);check(MasterKey.Protected(packet)&&!Encoding.UTF8.GetString(File.ReadAllBytes(pack)).Contains("FAKE COOKIE STATE"),"完整备份整体加密，主密码保护备份密钥");
            var envelope=migrated.OpenBundleKeys(packet);check(envelope.Preview.Accounts[0].Name==account.Name&&envelope.Preview.Accounts[0].Password=="","恢复预览不含密码明文");
            string damaged=Path.Combine(root,"damaged.bampack");byte[] bad=File.ReadAllBytes(pack);bad[bad.Length-40]^=1;File.WriteAllBytes(damaged,bad);check(Reject(()=>FullBackup.Prepare(fixedHome,damaged,migrated.OpenBundleKeys(packet)))&&vault.SequenceEqual(File.ReadAllBytes(migrated.FilePath)),"备份密文篡改在解压和替换前被拒绝");
            using(var stage=FullBackup.Prepare(fixedHome,pack,envelope)){check(stage.Manifest.Files.Count==DataDirectory.Inventory(fixedHome).Count&&File.ReadAllText(Path.Combine(stage.Path,"data","browser","chrome",account.Id,"Default","Cookies"))=="FAKE COOKIE STATE","完整备份还原并逐文件核对网页资料");check(Reject(()=>FullBackup.Publish(stage,()=>false,h=>{}))&&vault.SequenceEqual(File.ReadAllBytes(migrated.FilePath)),"取消或锁定时不得发布恢复资料");}
            check(!Directory.GetDirectories(root,"fixed.stage-*").Any(),"取消恢复后清理本次暂存，当前资料保留");
            using(var stage=FullBackup.Prepare(fixedHome,pack,migrated.OpenBundleKeys(packet))){File.WriteAllText(Path.Combine(fixedHome,"data","KEEP_CURRENT"),"CURRENT");string previous=FullBackup.Publish(stage,()=>true,h=>{});check(File.Exists(Path.Combine(previous,"data","KEEP_CURRENT"))&&!File.Exists(Path.Combine(fixedHome,"data","KEEP_CURRENT")),"整套恢复前将当前目录另存，不删除原资料");check(DataDirectory.Ready(fixedHome)&&vault.SequenceEqual(File.ReadAllBytes(Path.Combine(fixedHome,"data","vault-v2.bin"))),"恢复保留备份时的加密格式和账号资料字节");}
            migrated.Lock();migrated.Unlock(Password);var changed=migrated.Load();changed.Accounts[0].Note="FAKE EDIT";migrated.Save(changed);string daily=Path.Combine(fixedHome,"backups","accounts",DateTime.Now.ToString("yyyy-MM-dd")+".bav");check(File.Exists(daily)&&MasterKey.Protected(File.ReadAllBytes(daily)),"每日首次保存自动保留受保护账号备份");byte[] dailyBytes=File.ReadAllBytes(daily);changed.Accounts[0].Note="FAKE SECOND EDIT";migrated.Save(changed);check(dailyBytes.SequenceEqual(File.ReadAllBytes(daily)),"同日自动备份不反复覆盖此前版本");
            check(Reject(()=>FullBackup.Create(migrated,Path.Combine(fixedHome,"data","recursive.bampack"),null,h=>{})),"完整备份不可放在被备份的数据树中");
            var foreign=new Store(Path.Combine(root,"foreign"));foreign.PasswordIterations=10000;foreign.Save(Store.Initial());check(Reject(()=>foreign.OpenBundleKeys(packet)),"未解锁的另一主密码不能读取完整备份");check(foreign.OpenBundleKeys(packet,Password).Preview.Accounts.Count==1,"可用备份原主密码读取恢复预览，不替换当前保护设置");
            var validName=typeof(FullBackup).GetMethod("ValidName",BindingFlags.Static|BindingFlags.NonPublic);check(new[]{"../escape","data/../escape","data/C:/escape","data/CON","data/name.","data\\escape"}.All(n=>!(bool)validName.Invoke(null,new object[]{n})),"拒绝越界路径、设备名和 Windows 路径别名");
            var unknown=LoginStatus.Read(fixedHome,changed.Accounts[0]);check(unknown.Text.Contains("尚未确认")&&unknown.Text.Contains("已记住"),"已登记不会误报登录成功");changed.Accounts[0].LoginState="pending";check(LoginStatus.Read(fixedHome,changed.Accounts[0]).Text.Contains("等待"),"启动仅提示等待核对");changed.Accounts[0].LoginState="needs-auth";check(LoginStatus.Read(fixedHome,changed.Accounts[0]).Attention&&LoginStatus.Read(fixedHome,changed.Accounts[0]).Next.Contains("网页登录"),"认证失败提示明确的国服网页登录下一步");changed.Accounts[0].LoginState="confirmed";changed.Accounts[0].LoginCheckedUtc=DateTime.UtcNow;migrated.Save(changed);check(Math.Abs((migrated.Load().Accounts[0].LoginCheckedUtc-changed.Accounts[0].LoginCheckedUtc).TotalMilliseconds)<1&&LoginStatus.Read(fixedHome,changed.Accounts[0]).Text.Contains("上次"),"用户确认作为历史结果保存，不承诺永久在线");
            string seed=Totp.NewSecret();var recovery=Totp.NewRecoveryCodes();migrated.EnableTwoFactor(Password,seed,Totp.Code(seed,Totp.Step(DateTime.UtcNow)),recovery);string factorPack=Path.Combine(root,"factor.bampack");FullBackup.Create(migrated,factorPack,null,h=>{});byte[] factorPacket=FullBackup.ReadKeyPacket(factorPack);check(MasterKey.HasFactor(factorPacket)&&Reject(()=>foreign.OpenBundleKeys(factorPacket,Password)),"两步验证完整备份不能只用主密码打开");check(foreign.OpenBundleKeys(factorPacket,Password,recovery[0]).Preview.Accounts.Count==1,"完整备份可用原主密码和备用码读取，不改变当前保护设置");
            var window=new MainWindow(true,"CN",Path.Combine(root,"ui"));try{Entry.Render(window,Path.Combine(Path.GetDirectoryName(report),"preview-management.png"),1100,920);var dialog=new RestorePreviewDialog(null,Store.Initial(),envelope.Preview,true,envelope.CreatedUtc);try{Entry.Render(dialog,Path.Combine(Path.GetDirectoryName(report),"preview-restore.png"),580,630);}finally{dialog.Close();}}finally{window.Close();}
            migrated.Lock();foreign.Lock();rows.Add("仅使用虚构密码、网页登录文件与工作目录；未读取真实账号密码、未修改真实战网配置。");File.WriteAllLines(report,rows,new UTF8Encoding(true));
        }
    }
}
